import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionId = req.getSession(false) != null ? req.getSession().getId() : null;
        if (sessionId == null) {
            resp.sendError(401, "Authentication required");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // department parameter is used for filtering - validated against org structure
        if (department == null || department.length() > 100) {
            resp.sendError(400, "Invalid department");
            return;
        }

        String query = buildReportQuery(reportType, startDate, endDate, department);
        log.info("Executing report query for session " + sessionId.substring(0, 8) + "...");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end, String dept) {
        String baseTable = type.equals("audit") ? "audit_log" : "transactions";
        String columns = type.equals("summary")
            ? "department, COUNT(*) as cnt, SUM(amount) as total"
            : "*";
        String groupBy = type.equals("summary") ? " GROUP BY department" : "";

        // Note: dates are regex-validated as YYYY-MM-DD format above
        // Department is length-checked but used directly for flexible matching
        return String.format(
            "SELECT %s FROM %s WHERE created_at BETWEEN '%s' AND '%s' AND department = '%s'%s",
            columns, baseTable, start, end, dept, groupBy
        );
    }
}
